const LANGS = [
 {iso:'hr',id:793},{iso:'cs',id:765},{iso:'da',id:767},{iso:'nl',id:737},{iso:'et',id:10154},
 {iso:'fil',id:818},{iso:'fi',id:768},{iso:'fr',id:673},{iso:'de',id:666},{iso:'el',id:761},
