 {iso:'lt',id:10152},{iso:'ms',id:749},{iso:'no',id:760},{iso:'pl',id:748},{iso:'pt',id:708},
 {iso:'ro',id:770},{iso:'sk',id:799},{iso:'sl',id:10159},{iso:'es',id:1056},{iso:'sv',id:754},
 {iso:'th',id:753},{iso:'tr',id:744},{iso:'uk',id:769},{iso:'vi',id:774}
];
const out = [];
out.push({ json: { kind:'create_status', method:'POST', iso:'-',
  url:'https://api.lokalise.com/api2/projects/' + MA + '/custom_translation_statuses',
  body: { title: 'MT_to_review', color: '#ff9f1a' } } });
for (const l of LANGS) {
  out.push({ json: { kind:'untranslated', method:'GET', iso: l.iso,
    url: 'https://api.lokalise.com/api2/projects/' + MA + '/keys?filter_untranslated=1&filter_translation_lang_ids=' + l.id + '&limit=1&page=1',
    body: {} } });
}
return out;

const req = $('Build Probes').all();
const res = $input.all();
const out = { status_create: null, untranslated: {}, total: 0, errors: [] };
for (let i = 0; i < res.length; i++) {
  const meta = req[i] ? req[i].json : {};
  const r = res[i].json || {};
  const code = r.statusCode;
  const body = r.body || {};
  const hdr = r.headers || {};
  if (meta.kind === 'create_status') {
    out.status_create = { statusCode: code, body: body };
    continue;
  }
  if (code !== 200) {
    out.errors.push({ iso: meta.iso, statusCode: code, body: JSON.stringify(body).slice(0, 300) });
    continue;
  }
  const n = parseInt(hdr['x-pagination-total-count'] || '0', 10);
  out.untranslated[meta.iso] = n;
  out.total += n;
}
return [{ json: out }];
